# -*- coding: utf-8 -*-
"""MANAPRINT — BROWN 14 boules · maquette CANVA de Maeva (25/11/2026, « brown14_canva_12_A4 »).
Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 colonnes x 4 rangées),
traits de coupe en pointillés. Chaque billet : cadre arrondi, pastille « N° », titre BROWN,
l'hibiscus (image de la maquette, rangée aussi DANS ce fichier), la bande B · I · N · G · O
et les 14 cases à coins ronds (N au centre : 2 cases).
Le dessin est rejoué TRAIT POUR TRAIT depuis la maquette et enregistré une seule fois
par document (fichier léger, impression d'une traite).
RÈGLE (inchangée) — B 1-15 (x3) · I 16-30 (x3) · N 31-45 (x2) · G 46-60 (x3) · O 61-75 (x3)
   14 numéros, rangés du plus petit en haut au plus grand en bas. Crieur 1 à 75.
Chiffres comme la maquette : écriture à empattements (Times), 30 pt (le maximum).
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp).
(L'ancien brown14.py reste dans le dossier, il n'est plus appelé.)"""
import io, os as _os, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
GRIS = colors.Color(.45, .45, .45)
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Times-Roman", 30     # comme la maquette (Liberation Serif 30 pt)

# colonnes : (centre x, plage, lignes de base des cases du haut vers le bas)
_L3 = (72.87165, 43.39134, 13.91102)
COLONNES = [(33.95906, (1, 15), _L3), (87.13701, (16, 30), _L3),
            (140.315, (31, 45), (58.1315, 28.65118)),
            (193.4929, (46, 60), _L3), (246.6709, (61, 75), _L3)]
_HIBISCUS = (238.1102, 113.2806, 32.31496, 28.1682)
_IMG = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "brown14_v2_hibiscus.png")

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _image_hibiscus():
    if _os.path.exists(_IMG):
        return _IMG
    import base64
    from reportlab.lib.utils import ImageReader
    return ImageReader(io.BytesIO(base64.b64decode(_HIBISCUS_PNG)))


def _numeros(rng):
    for _ in range(400):
        t = tuple(tuple(sorted(rng.sample(range(lo, hi + 1), len(lignes))))
                  for _x, (lo, hi), lignes in COLONNES)
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_b14_modele", False):
        return
    f = {"{HB}": c._doc.getInternalFontName("Helvetica-Bold"),
         "{H}": c._doc.getInternalFontName("Helvetica")}
    def _p(s):
        for k, v in f.items():
            s = s.replace(k, v)
        return s
    c.beginForm("BROWN14_DESSIN", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + _p(_DESSIN_A))
    x, y, w, h = _HIBISCUS
    c.drawImage(_image_hibiscus(), x, y, w, h, mask="auto")
    c._code.append(_p(_DESSIN_B) + "\nQ")
    c.endForm()
    c._b14_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("BROWN14_DESSIN")
    _txt(c, "%06d" % serie, 44.00571, 127.2756, "Helvetica", 7.2, GRIS)
    for (cx, _pl, lignes), valeurs in zip(COLONNES, nums):
        for y, v in zip(lignes, valeurs):
            _txt(c, str(v), cx, y, POLICE_NUM, T_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 1414)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  \u00b7  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in (1, 2):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in (1, 2, 3):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


